.card-body {
  padding: 1rem;
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.card-excerpt {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: 1rem;
}

.card-meta {
  font-size: 0.8rem;
  color: var(--color-text-light);
  text-transform: uppercase;
}

/* Slideshow / Lightbox */
.slideshow-container {
  position: relative;
  max-width: 800px;
  margin: 2rem auto;
  border: 1px solid var(--color-border);
}

.slideshow-slide {
  display: none;
  padding: 2rem;
