  background: #f9f9f9;
}

.slideshow-slide.is-active {
  display: block;
}

.slideshow-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 1rem;
}

.slideshow-btn {
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.5rem 1rem;
  cursor: pointer;
}

/* Newsletter Form */
.newsletter-form {
  display: flex;
  gap: 0.5rem;
  max-width: 400px;
